<?php
/* SaaS Customer-style List Filter Cleanup v3
 * Usage: php business_admin_list_filters_cleanup_patch.php --dry-run | --apply | --rollback=BACKUP_ID
 * Requires the previously installed Customers Master List v2 patch.
 */
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only.');}
$root=__DIR__;
if(!is_file($root.'/artisan')){fwrite(STDERR,"Place this patch in the Laravel project root next to artisan.\n");exit(1);}
$action='dry-run';$rollbackId=null;
foreach(array_slice($argv,1) as $arg){
 if($arg==='--dry-run')$action='dry-run';
 elseif($arg==='--apply')$action='apply';
 elseif(str_starts_with($arg,'--rollback=')){$action='rollback';$rollbackId=substr($arg,11);}
 else{fwrite(STDERR,'Unknown option: '.$arg.PHP_EOL);exit(2);}
}
$backupBase=$root.'/storage/app/customer_list_filter_v3_backups';
$sha=static fn(string $path):?string=>is_file($path)?hash_file('sha256',$path):null;
$resolve=static function(string $relative)use($root):string{
 if(!preg_match('~^(?:app/Http/Controllers/Public/Business/Admin/|resources/views/public/business/admin/)[A-Za-z0-9_./-]+\.php$~',$relative)||str_contains($relative,'..')||str_contains($relative,'//'))
   throw new RuntimeException('Invalid file path: '.$relative);
 $p=$root;foreach(explode('/',$relative) as $name){$p.='/'.$name;if(is_link($p))throw new RuntimeException('Symlink path denied: '.$relative);}
 return $root.'/'.$relative;
};
try{
 if($action==='rollback'){
  if(!preg_match('/^[a-zA-Z0-9_-]{5,80}$/',(string)$rollbackId))throw new RuntimeException('Invalid backup ID.');
  $dir=$backupBase.'/'.$rollbackId;
  if(!is_file($dir.'/manifest.json'))throw new RuntimeException('Backup not found: '.$rollbackId);
  $state=json_decode(file_get_contents($dir.'/manifest.json'),true,512,JSON_THROW_ON_ERROR);
  if(($state['patch']??'')!=='saas-admin-compact-filter-cleanup-v3')throw new RuntimeException('Wrong backup type.');
  foreach($state['changed'] as $relative=>$change){
   $target=$resolve($relative);
   if($sha($target)!==$change['after'])throw new RuntimeException('Rollback blocked; file changed after installation: '.$relative);
   if($sha($dir.'/files/'.$relative)!==$change['before'])throw new RuntimeException('Backup missing/corrupted: '.$relative);
  }
  foreach($state['changed'] as $relative=>$change){
   $target=$resolve($relative);
   if(!copy($dir.'/files/'.$relative,$target)||$sha($target)!==$change['before'])throw new RuntimeException('Unable to restore: '.$relative);
  }
  echo 'ROLLBACK OK: '.count($state['changed']).' files restored.'.PHP_EOL;exit(0);
 }
 $compressed=base64_decode('',true);
 if($compressed===false||($raw=gzdecode($compressed))===false)throw new RuntimeException('Corrupted patch bundle.');
 $bundle=json_decode($raw,true,512,JSON_THROW_ON_ERROR);
 if(($bundle['id']??'')!=='saas-admin-compact-filter-cleanup-v3')throw new RuntimeException('Unexpected patch bundle.');
 $pending=[];$upToDate=0;
 // Validate EVERY affected file before changing ANY file.
 foreach($bundle['manifest'] as $relative=>$entry){
  $target=$resolve($relative);$current=$sha($target);
  if($current===$entry['to']){$upToDate++;continue;}
  if($current!==$entry['from'])throw new RuntimeException('Local file differs from the supported Customers Master v2 version: '.$relative."\nNo files changed. Merge this file manually or restore the expected version; do not force overwrite.");
  $bytes=base64_decode($bundle['files'][$relative]??'',true);
  if($bytes===false||strlen($bytes)!==$entry['length']||hash('sha256',$bytes)!==$entry['to'])throw new RuntimeException('Patch payload mismatch: '.$relative);
  $pending[$relative]=['bytes'=>$bytes,'before'=>$current,'after'=>$entry['to']];
 }
 echo count($bundle['manifest']).' files checked; '.count($pending).' require updates; '.$upToDate.' already current.'.PHP_EOL;
 if($action==='dry-run'){echo 'DRY RUN OK; no changes made.'.PHP_EOL;exit(0);}
 if(!$pending){echo 'ALREADY INSTALLED.'.PHP_EOL;exit(0);}
 if(!is_dir($backupBase)&&!mkdir($backupBase,0775,true)&&!is_dir($backupBase))throw new RuntimeException('Cannot create backup directory.');
 $backupId=date('Ymd_His').'-'.bin2hex(random_bytes(4));$dir=$backupBase.'/'.$backupId;
 if(!mkdir($dir.'/files',0775,true))throw new RuntimeException('Cannot create backup folder.');
 $state=['patch'=>'saas-admin-compact-filter-cleanup-v3','created_at'=>date(DATE_ATOM),'changed'=>[]];
 foreach($pending as $relative=>$entry){
  $saved=$dir.'/files/'.$relative;$parent=dirname($saved);
  if(!is_dir($parent)&&!mkdir($parent,0775,true)&&!is_dir($parent))throw new RuntimeException('Cannot create backup subfolder: '.$relative);
  $target=$resolve($relative);
  if(!copy($target,$saved)||$sha($saved)!==$entry['before'])throw new RuntimeException('Failed to verify backup: '.$relative);
  $state['changed'][$relative]=['before'=>$entry['before'],'after'=>$entry['after']];
 }
 if(file_put_contents($dir.'/manifest.json',json_encode($state,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))===false)throw new RuntimeException('Cannot write backup manifest.');
 $written=[];
 try{
  foreach($pending as $relative=>$entry){
   $target=$resolve($relative);$written[]=$relative;
   if(file_put_contents($target,$entry['bytes'],LOCK_EX)!==strlen($entry['bytes'])||$sha($target)!==$entry['after'])throw new RuntimeException('Update verification failed: '.$relative);
  }
 }catch(Throwable $e){foreach(array_reverse($written) as $relative)@copy($dir.'/files/'.$relative,$resolve($relative));throw $e;}
 echo 'APPLY OK: '.count($written).' files updated.'.PHP_EOL;
 echo 'Backup ID: '.$backupId.PHP_EOL;
 echo 'Rollback: php '.basename(__FILE__).' --rollback='.$backupId.PHP_EOL;
 echo 'Next: php artisan view:clear && php artisan optimize:clear'.PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,'ERROR: '.$e->getMessage().PHP_EOL);exit(1);}
